//go:build amd64

package floats

// Unfused elementwise kernels and the pairwise-sum block, generated by go-asmgen
// (nofma_amd64_gen.go) into nofma_amd64.s: plain AVX multiplies, adds and
// subtracts, no VFMADD. The callers pass every slice already sliced to the common
// length; pwBlockAVX2 requires 8 <= len(a) <= 128.
func axpyNoFMAAVX2(alpha float64, x, y []float64)
func xpbyNoFMAAVX2(beta float64, x, y []float64)
func axpby3NoFMAAVX2(dst []float64, alpha float64, a []float64, beta float64, b []float64, gamma float64, c []float64)
func axpyDiffNoFMAAVX2(dst, a []float64, f float64, b, c []float64)
func pwBlockAVX2(a []float64) float64

// The NoFMA kernels and the pairwise block share the gate of the other AVX2
// kernels (hasAVX2FMA, kernels_amd64.go); they use no FMA instruction, so the gate
// is stricter than necessary on the rare AVX2 part without FMA3, which takes the
// portable path, with identical results.

func axpyNoFMA(alpha float64, x, y []float64) {
	if hasAVX2FMA {
		axpyNoFMAAVX2(alpha, x, y)
		return
	}
	axpyNoFMARef(alpha, x, y)
}

func xpbyNoFMA(beta float64, x, y []float64) {
	if hasAVX2FMA {
		xpbyNoFMAAVX2(beta, x, y)
		return
	}
	xpbyNoFMARef(beta, x, y)
}

func axpby3NoFMA(dst []float64, alpha float64, a []float64, beta float64, b []float64, gamma float64, c []float64) {
	if hasAVX2FMA {
		axpby3NoFMAAVX2(dst, alpha, a, beta, b, gamma, c)
		return
	}
	axpby3NoFMARef(dst, alpha, a, beta, b, gamma, c)
}

func axpyDiffNoFMA(dst, a []float64, f float64, b, c []float64) {
	if hasAVX2FMA {
		axpyDiffNoFMAAVX2(dst, a, f, b, c)
		return
	}
	axpyDiffNoFMARef(dst, a, f, b, c)
}

func pairwiseBlock(a []float64) float64 {
	if hasAVX2FMA {
		return pwBlockAVX2(a)
	}
	return pairwiseBlockRef(a)
}
